class Solver:
    def __init__(self):
        self._lim = None
        if threadpool_limits is not None:
            try:
                self._lim = threadpool_limits(limits=1)
            except Exception:
                pass

    def solve(self, problem, **kwargs):
        A = problem["matrix"]
        k = problem["k"]
        N = A.shape[0]
        v0 = np.ones(N, dtype=A.dtype)
        if A.format != "csr":
            A = A.tocsr()
        indptr, indices, data = A.indptr, A.indices, A.data
        params = _UnsymmetricArpackParams(N, k, A.dtype.char, lambda x: A @ x, 1,
